package com.mahesh.empleave.notification;import com.mahesh.empleave.common.dto.*;import com.mahesh.empleave.user.*;import lombok.*;import org.springframework.data.domain.*;import org.springframework.security.core.*;import org.springframework.transaction.annotation.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/notifications") @RequiredArgsConstructor public class NotificationController{private final NotificationRepository repo;private final UserRepository users;@GetMapping Page<ApiDtos.Notification> mine(Authentication a,@RequestParam(defaultValue="all") String state,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){var u=users.findByEmail(a.getName()).orElseThrow();var p=PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending());return ("unread".equalsIgnoreCase(state)?repo.findByUserAndReadAtIsNull(u,p):"read".equalsIgnoreCase(state)?repo.findByUserAndReadAtIsNotNull(u,p):repo.findByUser(u,p)).map(ApiDtos::notification);}@GetMapping("/unread-count") Map<String,Long> unread(Authentication a){return Map.of("count",repo.countByUserAndReadAtIsNull(users.findByEmail(a.getName()).orElseThrow()));}@PutMapping("/{id}/read") @Transactional ApiDtos.Notification read(Authentication a,@PathVariable Long id){var n=repo.findById(id).orElseThrow();if(!n.getUser().getEmail().equals(a.getName()))throw new SecurityException("Not your notification");n.markRead();return ApiDtos.notification(n);}}
